const presets={naval:['battleship','submarine'],air:['fighter','fighter'],bombing:['battleship','bomber'],nuclear:['nuclear','nuclear'],asw:['submarine','carrier'],hardened:['nuclear','airbase'],population:['nuclear','population'],airdefense:['silo','fighter']};
